This is a miscompilation bug in SLPVectorizer.
Issue title: [SLPVectorizer] Miscompile in slp vectorizer (shift produces poison)
Detailed information:
Source:
target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128"
target triple = "x86_64-unknown-linux-gnu"
define float @test(i8 %0) {
entry:
  %1 = sext i8 0 to i32
  %2 = lshr i32 %1, 27
  %3 = sext i8 %0 to i32
  %reass.add.epil = mul i32 %3, 2
  %4 = or i32 %reass.add.epil, %2
  switch i32 %4, label %exit [
    i32 0, label %exit
    i32 1, label %exit
  ]

exit:                                             ; preds = %entry, %entry, %entry
  ret float 0.000000e+00
}

Target:
; ModuleID = '<stdin>'
source_filename = "<stdin>"
target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128"
target triple = "x86_64-unknown-linux-gnu"

define float @test(i8 %0) {
entry:
  %1 = insertelement <2 x i8> <i8 poison, i8 0>, i8 %0, i32 0
  %2 = sext <2 x i8> %1 to <2 x i16>
  %3 = mul <2 x i16> %2, <i16 2, i16 27>
  %4 = lshr <2 x i16> %2, <i16 2, i16 27>
  %5 = shufflevector <2 x i16> %3, <2 x i16> %4, <2 x i32> <i32 0, i32 3>
  %6 = extractelement <2 x i16> %5, i32 0
  %7 = sext i16 %6 to i32
  %8 = extractelement <2 x i16> %5, i32 1
  %9 = zext i16 %8 to i32
  %10 = or i32 %7, %9
  switch i32 %10, label %exit [
    i32 0, label %exit
    i32 1, label %exit
  ]

exit:                                             ; preds = %entry, %entry, %entry
  ret float 0.000000e+00
}

Transformation doesn't verify!

ERROR: Source is more defined than target

Example:
i8 %#0 = #x03 (3)

Source:
i32 %#1 = #x00000000 (0)
i32 %#2 = #x00000000 (0)
i32 %#3 = #x00000003 (3)
i32 %reass.add.epil = #x00000006 (6)
i32 %#4 = #x00000006 (6)
  >> Jump to %exit

Target:
<2 x i8> %#1 = < #x03 (3), #x00 (0) >
<2 x i16> %#2 = < #x0003 (3), #x0000 (0) >
<2 x i16> %#3 = < #x0006 (6), #x0000 (0) >
<2 x i16> %#4 = < #x0000 (0), poison >
<2 x i16> %#5 = < #x0006 (6), poison >
i16 %#6 = #x0006 (6)
i32 %#7 = #x00000006 (6)
i16 %#8 = poison
i32 %#9 = poison
i32 %#10 = poison
UB triggered on switch


Summary:
  0 correct transformations
  1 incorrect transformations
  0 failed-to-prove transformations
  0 Alive2 errors

